def find_topmost_carpet(n, carpets, point):
    """
    Finds the topmost carpet covering a given point.

    Args:
    n (int): The total number of carpets.
    carpets (list of tuples): Each tuple (a, b, g, k) represents the bottom-left corner (a, b)
                              of a carpet and its width g and height k.
    point (tuple): The point (x, y) to check.

    Returns:
    int: The 1‑based index of the topmost carpet covering the point, or -1 if none.
    """
    try:
        # Validate inputs
        if not isinstance(n, int) or n < 0:
            raise ValueError("n must be a non‑negative integer")
        if not isinstance(carpets, list) or len(carpets) != n:
            raise ValueError("carpets must be a list of length n")
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError("point must be a tuple of two integers")
        x, y = point

        # Iterate from the topmost carpet (last) to the bottom
        for idx in range(n - 1, -1, -1):
            a, b, g, k = carpets[idx]
            if not all(isinstance(v, (int, float)) for v in (a, b, g, k)):
                raise ValueError("carpet coordinates and dimensions must be numeric")
            if a <= x <= a + g and b <= y <= b + k:
                return idx + 1  # Convert 0‑based index to 1‑based

        return -1
    except Exception:
        return -1

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Convert a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, ordered from the highest degree term to the constant term.
    :return: The string representation of the polynomial following the formatting rules.
    """
    pieces = []
    for index, coeff in enumerate(coeffs):
        degree = n - index
        if coeff == 0:
            continue

        # Determine sign
        if not pieces:
            sign = '' if coeff > 0 else '-'
        else:
            sign = '+' if coeff > 0 else '-'

        abs_val = abs(coeff)

        # Determine coefficient part
        if abs_val == 1 and degree > 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_val)

        # Determine variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        piece = f"{sign}{coeff_part}{var_part}"
        pieces.append(piece)

    if not pieces:
        return '0'
    return ''.join(pieces)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Validate that encoded and original strings are of same length
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping from encoded -> original
    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"  # Contradiction
        else:
            mapping[enc_char] = orig_char

    # Ensure every character in message has a mapping
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)
